# -*- coding: utf-8 -*-
# «Неверный вариант = ключ без единицы измерения» (свип unit_sweep) + условия, зависящие от соседней задачи, + искажённые ключи. 26.09
import json, psycopg2
c = psycopg2.connect("postgresql://algo:algo_password@algo-content-db:5432/algo_content").cursor()
H = {(t, i): (k, v) for t, i, k, v in json.load(open("/audit/unit_hits.json"))}
def dv(t, i):
    c.execute("SELECT distractor_meta FROM tasks_master WHERE id=%s", (t,)); d = c.fetchone()[0][i]; return d.get("value_latex") or d.get("value")
S = "сверка вариантов с ключом + условие задачи, 26.09"
P = {}
for t, i in [("G6_TB_81–83_678.2", 1), ("G6_TB_81–83_678.3", 1), ("G6_TB_11–12_113.2", 0), ("G5_TB_8_128.3", 2), ("G11_TB_16_2*_16_6", 2),
             ("G6_TB_81–83_699.1", 2), ("G6_TB_81–83_699.2", 2), ("G6_TB_81–83_699.3", 2), ("G6_TB_81–83_699.4", 1), ("G6_TB_81–83_699.5", 1), ("G6_TB_81–83_699.6", 2)]:
    k, v = H[(t, i)]
    P[t] = dict(drop=[i], src=S, why=f"вариант «{v}» совпадает с ключом «{k}» (отличается только записью единицы измерения / обозначения) — верный ответ среди неверных, закрыт")
P["G6_TB_81–83_699.5"]["dadd"] = [(r"$+7^{\circ}\mathrm{C}$ и $-7^{\circ}\mathrm{C}$", "Ученик не различает тепло и мороз и записал оба знака.")]
P["G6_TB_81–83_712"] = dict(drop=[1], src=S, why="вариант «(−2 и −4), (−1 и −5), (0 и −6), (1 и −7)» — те же пары, что в ключе, в другом порядке, т. е. верный ответ среди неверных — закрыт")
P["G6_TB_136–138_1103.2.1"] = dict(q=r"Одна из сторон треугольника $6{,}5$ см, вторая сторона $a$ см, третья сторона $b$ см. Найдите периметр треугольника, если $a = 5{,}8$ см, $b = 4{,}6$ см.",
    src=S, why="условие ссылалось на «найденное выражение» из соседнего подпункта и само по себе было нерешаемо — данные подпункта 1 включены в условие; 6,5 + 5,8 + 4,6 = 16,9")
P["G6_TB_136–138_1103.2.2"] = dict(q=r"Одна из сторон треугольника $6{,}5$ см, вторая сторона $a$ см, третья сторона $b$ см. Найдите периметр треугольника, если $a = 7{,}3$ см, $b = 8{,}2$ см.",
    src=S, why="условие ссылалось на «найденное выражение» из соседнего подпункта и само по себе было нерешаемо — данные подпункта 1 включены в условие; 6,5 + 7,3 + 8,2 = 22")
P["G6_TB_30_1168.1"] = dict(k=r"$s = (a - b)t$; $s = 0{,}2$ км", src=S, why="ключ был искажён («·t. а) s=0, 2 км»); s = (a − b)t = 0,6 · 1/3 = 0,2 км")
Q69 = ("Костя и Вера вышли одновременно из одного и того же пункта в противоположных направлениях. Костя идёт со скоростью $a$ км/ч, а Вера — со скоростью $b$ км/ч. "
       "Какое расстояние будет между ними через $t$ ч? Составьте формулу для решения задачи, обозначив искомое расстояние (в километрах) буквой $s$. Найдите по формуле ")
W69 = "условие «Решите предыдущую задачу, заменив слова…» не решалось без соседней задачи — подставлен полный текст задачи 1168 с заменой по учебнику; "
P["G6_TB_30_1169.1"] = dict(q=Q69 + r"$s$, если $a=4{,}2$, $b=3{,}6$, $t=\dfrac{1}{3}$.", k=r"$s = (a + b)t$; $s = 2{,}6$ км", src=S, why=W69 + "ключ был искажён («·t. а) s=2, 6 км»): s = (a + b)t = 7,8 · 1/3 = 2,6 км")
P["G6_TB_30_1169.2"] = dict(q=Q69 + r"$a$, если $s=2{,}2$, $b=3{,}2$, $t=\dfrac{1}{4}$.", src=S, why=W69 + "a = s/t − b = 8,8 − 3,2 = 5,6")
P["G6_TB_30_1169.3"] = dict(q=Q69 + r"$b$, если $s=1{,}5$, $a=5{,}4$, $t=\dfrac{1}{6}$.", src=S, why=W69 + "b = s/t − a = 9 − 5,4 = 3,6")
P["G6_TB_30_1169.4"] = dict(q=Q69 + r"$t$, если $s=5{,}6$, $a=5{,}1$, $b=3{,}3$.", src=S, why=W69 + "t = s/(a + b) = 5,6 : 8,4 = 2/3")
for t, word in [("G5_TB_42_745.1", "убывания"), ("G5_TB_42_745.2", "возрастания")]:
    P[t] = dict(k=dv(t, 0), src=S, why=f"вариант с полным списком всех семи дробей в порядке {word} (равные рядом) — верный ответ, а ключом был укороченный список различных значений; полный список сделан ключом, вариант закрыт")
P["G5_TB_42_745.2"]["dadd"] = [(dv("G5_TB_42_745.1", 0), "Ученик расположил дроби в порядке убывания вместо порядка возрастания.")]
